#include <iostream>
#include <vector>
#include <algorithm>
using namespace std;
using lint = long long;
const lint MOD = 1000000007;

struct Mtx {
    int r, c;
    vector<vector<lint>> v;
    Mtx(int n = 0) : r(n), c(n), v(n, vector<lint>(n, 0)) {}
    Mtx(int rr, int cc) : r(rr), c(cc), v(rr, vector<lint>(cc, 0)) {}
    lint& operator()(int i, int j) { return v[i][j]; }
    const lint& operator()(int i, int j) const { return v[i][j]; }
    Mtx operator*(const Mtx& o) const {
        Mtx res(r, o.c);
        for (int i = 0; i < r; ++i)
            for (int k = 0; k < c; ++k)
                if (v[i][k])
                    for (int j = 0; j < o.c; ++j)
                        res(i, j) = (res(i, j) + v[i][k] * o.v[k][j]) % MOD;
        return res;
    }
    static Mtx I(int n) {
        Mtx res(n);
        for (int i = 0; i < n; ++i) res(i, i) = 1;
        return res;
    }
};

Mtx qpow(Mtx base, int e) {
    Mtx res = Mtx::I(base.r);
    while (e) {
        if (e & 1) res = res * base;
        base = base * base;
        e >>= 1;
    }
    return res;
}

Mtx Base[65];

Mtx gen(int i, int K) {
    return qpow(Base[i + K], K - i) * qpow(Base[i], i);
}

lint proc(lint N, lint K) {
    if (N == 0) return 1;
    vector<lint> base_repr;
    lint x = N;
    while (x) {
        base_repr.push_back(x % K);
        x /= K;
    }
    reverse(base_repr.begin(), base_repr.end());
    int L = base_repr.size();
    vector<Mtx> T(L + 5), P(L + 5);
    T[0] = Base[K - 1];
    P[0] = qpow(T[0], K - 1);
    if (L > 1) {
        T[1] = gen(K - 1, K);
        P[1] = qpow(T[1], K - 1);
    }
    Mtx suf = Mtx::I(2 * K + 1);
    for (int j = 2; j <= L; ++j) {
        int idx = K - (j % K);
        if (idx == K) idx = 0;
        T[j] = gen(idx, K);
        suf = suf * P[j - 1];
        T[j] = T[j] * suf;
        P[j] = qpow(T[j], K - 1);
    }
    lint rem = N % K;
    N -= rem;
    lint sh = 0;
    x = N;
    if (x > 0) {
        while (x % K == 0) {
            ++sh;
            x /= K;
        }
    }
    sh = (K - sh % K) % K;
    Mtx ans = Mtx::I(2 * K + 1);
    ans = qpow(Base[sh], rem) * qpow(Base[sh + K], max(rem - sh, (lint)0));
    N /= K;
    if (!N) {
        return (ans(2 * K, 0) + ans(0, 0)) % MOD;
    }
    --N;
    vector<lint> digits;
    while (N) {
        digits.push_back(N % K);
        N /= K;
    }
    int p = 1;
    for (lint d : digits) {
        if (d > 0) ans = ans * qpow(T[p], d);
        ++p;
    }
    ans = ans * T[1];
    return (ans(2 * K, 0) + ans(0, 0)) % MOD;
}

int main() {
    lint N, K;
    cin >> N >> K;
    for (lint i = 0; i < 2 * K + 1; ++i) {
        Base[i] = Mtx(2 * K + 1, 2 * K + 1);
        for (lint j = 0; j < i; ++j) Base[i](0, j) = 1;
        for (lint j = 0; j < 2 * K - 1; ++j) Base[i](j + 1, j) = 1;
        Base[i](2 * K, 0) = 1;
        Base[i](2 * K, 2 * K) = 1;
    }
    cout << proc(N, K) << '\n';
    return 0;
}
